import{z as i,x as B,o as l,c as p,q as t,j as A,D as E,d as r,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"正则语言的封闭性","description":"","frontmatter":{"title":"正则语言的封闭性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/regular-closure.md","filePath":"cs/regular-closure.md","lastUpdated":1791063341000}'),d={name:"cs/regular-closure.md"};function m(D,a,C,F,u,f){const n=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=t('<h1 id="正则语言的封闭性" tabindex="-1">正则语言的封闭性 <a class="header-anchor" href="#正则语言的封闭性" aria-label="Permalink to &quot;正则语言的封闭性&quot;">​</a></h1><div class="epigraph"><p>并、连接、星、补、交、同态、逆同态都把正则语言送回正则；构造乘积机或替换字母，不必回到正则式。</p><footer>—— 据 Kleene, Representation of Events in Nerve Nets, 1956；Hopcroft and Ullman 整理</footer></div><p>上一课<a href="/cs/dfa-minimization">DFA 最小化与 Myhill–Nerode</a>给出正则的规范自动机。本课不重做划分。缺口是：<strong>对语言做集合运算之后还是否正则</strong>。封闭性既是构造工具，也是证非正则的杠杆（若 \\(L\\cap R\\) 非正则而 \\(R\\) 正则，则 \\(L\\) 非正则）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>已知 \\(L,R\\) 正则。并：正则式直接写 \\(+\\)，或 DFA 乘积取接受并。交：乘积取接受交。补：DFA 接受态翻转——这里必须是完全 DFA，NFA 直接翻会错。连接与星：NFA 上加 \\(\\varepsilon\\) 边最干净，再确定化。同态 \\(h:\\Sigma\\to\\Gamma^*\\) 把字母换成串，正则的像仍正则；逆同态更常用：正则的原像仍正则。</p><p>主干词法把多种别正则并成一张表，已经用过并。本课把清单收全，并强调<strong>补必须走 DFA</strong>。</p><h3 id="封闭不是「任意运算」" tabindex="-1">封闭不是「任意运算」 <a class="header-anchor" href="#封闭不是「任意运算」" aria-label="Permalink to &quot;封闭不是「任意运算」&quot;">​</a></h3><p>商 \\(L/R=\\{x\\mid \\exists y\\in R,xy\\in L\\}\\) 对正则也封闭，但无限并一般不封闭。置换成上下文无关语言可以破坏正则。本课清单以自动机可构造的为准。</p><p><span class="marginnote">Kleene 代数把并、连接、星当成正则的签名。Hopcroft–Ullman 用乘积机写交与补。逆同态是后课「把问题编成正则」时的标准手法。</span></p><p><span class="marginnote">常见误区：初学者对 NFA 直接翻接受态求补。NFA 的接受是「存在一条接受路」，翻转后「另有一条拒绝路」仍可能存在，结果既不是补也不是原语言——必须先确定化，保证每个串恰好一条路，翻转才有意义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>要证 \\(L\\) 非正则：找正则 \\(R\\) 使 \\(L\\cap R\\) 等于已知非正则（如 \\(a^nb^n\\)）。要证封闭：画乘积或改转移，不写「显然」。同态：把每条标 \\(a\\) 的边换成一条标 \\(h(a)\\) 的路径。</p>',12)),(l(),A(o,null,{default:E(()=>[s(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E6%AD%A3%E5%88%99%20L%2C%20R%22%5D%20--%3E%20PROD%5B%22%E4%B9%98%E7%A7%AF%EF%BC%9A%E4%BA%A4%20%2F%20%E5%B9%B6%22%5D%0A%20%20REG%20--%3E%20COMP%5B%22DFA%20%E7%BF%BB%E6%8E%A5%E5%8F%97%EF%BC%9A%E8%A1%A5%22%5D%0A%20%20REG%20--%3E%20HOM%5B%22%E5%90%8C%E6%80%81%20%2F%20%E9%80%86%E5%90%8C%E6%80%81%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/nfa-dfa"},"子集构造"),r("保证 NFA 侧的连接、星可回到 DFA。最小化可做可不做，封闭性不依赖状态数最小。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"乘积机状态是对 \\((p,q)\\)，同时模拟两个 DFA。补之所以简单，因为 DFA 对每个串恰好一条路：不接受即应接受。CFL 对补、交不封闭，这正是下一课要离开正则的原因之一——光靠布尔运算不够描述嵌套。",-1)),a[6]||(a[6]=e("p",null,"同态可以擦掉信息（\\(h(a)=h(b)=\\varepsilon\\)），所以同态像比原语言「更容易」正则；逆同态把字母表译码回来，常用来从简单语言造复杂实例。",-1)),a[7]||(a[7]=e("p",null,"同态可以擦符号，因此「正则的同态像」不能用来证明原语言正则——方向反了。逆同态保留正则，常把「看起来不规则」的编码还原成 \\(a^nb^n\\) 的切片。补的构造必须先确定化：NFA 接受路径存在性，翻接受态会把「另有一条路该拒绝」弄错。",-1)),a[8]||(a[8]=e("p",null,[e("span",{class:"marginnote"},"直觉类比：乘积机像两个人对同一串字符各自过一道安检——只有两人都放行（同时到达接受态），这个串才算同时在两个语言里。状态数是 \\(|Q_A|\\times|Q_B|\\)：各 3 个状态就乘出 9 个组合状态。")],-1)),(l(),A(o,null,{default:E(()=>[s(n,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22DFA%20A%20%E7%9A%84%E5%BD%93%E5%89%8D%E7%8A%B6%E6%80%81%20p%22%5D%20--%3E%20PAIR%5B%22%E4%B9%98%E7%A7%AF%E7%8A%B6%E6%80%81%20(p%2C%20q)%22%5D%0A%20%20S2%5B%22DFA%20B%20%E7%9A%84%E5%BD%93%E5%89%8D%E7%8A%B6%E6%80%81%20q%22%5D%20--%3E%20PAIR%0A%20%20PAIR%20--%3E%20STEP%5B%22%E8%AF%BB%E5%90%8C%E4%B8%80%E5%AD%97%E7%AC%A6%EF%BC%9Ap%20%E4%B8%8E%20q%20%E5%90%84%E8%B5%B0%E4%B8%80%E6%AD%A5%22%5D%0A%20%20STEP%20--%3E%20MORE%5B%22%E4%B8%B2%E6%9C%AA%E8%AF%BB%E5%AE%8C%EF%BC%9A%E7%BB%A7%E7%BB%AD%E8%B5%B0%22%5D%0A%20%20MORE%20--%3E%20PAIR%0A%20%20STEP%20--%3E%20ACC%7B%22%E8%AF%BB%E5%AE%8C%E4%BA%86%EF%BC%8Cp%20%E5%92%8C%20q%20%E9%83%BD%E5%9C%A8%E6%8E%A5%E5%8F%97%E5%90%97%3F%22%7D%0A%20%20ACC%20--%3E%7C%22%E6%98%AF%22%7C%20YES%5B%22%E4%B8%B2%E5%B1%9E%E4%BA%8E%20L(A)%20%E2%88%A9%20L(B)%22%5D%0A%20%20ACC%20--%3E%7C%22%E5%90%A6%22%7C%20NO%5B%22%E4%B8%B2%E4%B8%8D%E5%B1%9E%E4%BA%8E%E4%BA%A4%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证星高的完整代数公理，不引入正则语言的一阶逻辑刻画（Büchi）。不把 CFL 封闭性提前写完。后课默认：正则在布尔运算与（逆）同态下关闭；证非正则可以交一个正则「切片」。下一课为 CFG 配下推栈。</p><p>封闭性证明优先给自动机构造，再谈最小化——正确性不依赖状态最少。用封闭性证非正则时，切片语言必须已知非正则，不能循环论证。</p><p><span class="marginnote">术语翻译：逆同态就是「把压缩过的字符串还原成所有可能的原文集合，再问这个集合里有没有落在 \\(L\\) 中的成员」。直觉类比：快递被压成了摘要，逆同态把摘要展开成所有可能的原始包裹清单，逐个比对收件规则。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>并、交、补、连接、星、同态、逆同态保持正则。</li><li>补要完全 DFA；交用乘积。</li><li>与已知非正则相交，是排除正则的第二杠杆。</li><li>出处：Kleene, 1956；Hopcroft and Ullman。</li></ul>',6))])}const P=i(d,[["render",m]]);export{c as __pageData,P as default};
